+
+// --------------------------------------------------------------------------- documented checks (the guide)
+
+describe("A19 documented checks: docs/handover/backup-restore.md (DO-F)", () => {
+  it("documents R1–R9, measured drill timings, RPO/RTO 'to agree with Mobily IT' and an Arabic summary", () => {
