+      await restored.close();
+    }
+  }, 120_000);
+
+  it("the set appears in listBackupSets of the source for ADM_TECH; 403 without backup.read", async () => {
+    requireBuilt(BACKUP_SH);
+    const admin = await signIn(api.app, adminSubject);
