    worker = await inProcessWorker(env, boss);
    w = await orgWorld(env.api);
  }, 120_000);
  afterAll(async () => {
    await worker?.stop().catch(() => undefined);
    await boss?.stop({ graceful: false, wait: true, timeout: 5000 }).catch(() => undefined);
    await env?.close();
