+  let candidate = Date.UTC(local.getUTCFullYear(), local.getUTCMonth(), local.getUTCDate(), hour, minute) - offsetMs;
+  if (candidate <= from.getTime()) candidate += 86_400_000;
+  return new Date(candidate).toISOString();
