+    env: {
+      PATH: process.env["PATH"] ?? "",
+      HOME: process.env["HOME"] ?? tmpdir(),
+      TMPDIR: tmpdir(),
+      LANG: "C.UTF-8",
+      ...(PGBIN ? { PGBIN } : {}),
+      ...env,
+    },
+    encoding: "utf8",
+    timeout: 600_000,
+  });
+  return { status: r.status, out: `${r.stdout ?? ""}${r.stderr ?? ""}`, seconds: (performance.now() - t0) / 1000 };
+}
